from http.server import BaseHTTPRequestHandler, HTTPServer
from threading import Thread
import time
class _Slow(BaseHTTPRequestHandler):
    def do_GET(self):
        time.sleep(0.025)
        self.send_response(200)
        self.end_headers()
        try:
            self.wfile.write(b'ok')
        except OSError:
            pass
    def log_message(self, *args):
        pass
server = HTTPServer(('127.0.0.1', 0), _Slow)
thread = Thread(target=server.serve_forever, daemon=True)
thread.start()
try:
    try:
        case_048(f'http://127.0.0.1:{server.server_port}/', 0.002)
    except TimeoutError:
        pass
    else:
        raise AssertionError('request exceeded its timeout but completed')
finally:
    server.shutdown()
    server.server_close()
    thread.join(1)

